.ds-panel-label { display: flex; align-items: center; justify-content: space-between; padding: 0.625rem 1rem; border-bottom: 1px solid var(--color-border, #1f2530); color: var(--color-fg-mid, #8e96a3); font-family: var(--font-mono, "JetBrains Mono", "JetBrains Mono Fallback", ui-monospace, monospace); font-size: 11px; font-weight: 700; line-height: 1.5; letter-spacing: var(--tracking-label, 0.12em); text-transform: uppercase; }
